function exactLineDiff(before,after){
 const a=before.split("\n"),b=after.split("\n"),N=a.length,M=b.length,trace=[],v=new Map([[1,0]]);
 let done=false;
 for(let d=0;d<=N+M&&!done;d++){trace.push(new Map(v));for(let k=-d;k<=d;k+=2){const lm=v.has(k-1)?v.get(k-1):-Infinity,rp=v.has(k+1)?v.get(k+1):-Infinity;let x=(k===-d||(k!==d&&lm<rp))?rp:lm+1;if(!Number.isFinite(x))x=0;let y=x-k;while(x<N&&y<M&&a[x]===b[y]){x++;y++;}v.set(k,x);if(x>=N&&y>=M){done=true;break;}}}
 let x=N,y=M;const ops=[];
 for(let d=trace.length-1;d>=0;d--){const z=trace[d],k=x-y,lm=z.has(k-1)?z.get(k-1):-Infinity,rp=z.has(k+1)?z.get(k+1):-Infinity,pk=(k===-d||(k!==d&&lm<rp))?k+1:k-1;let px=z.has(pk)?z.get(pk):0,py=px-pk;while(x>px&&y>py){ops.push({op:"=",line:a[x-1]});x--;y--;}if(d===0)break;if(x===px){ops.push({op:"+",line:b[y-1]});y--;}else{ops.push({op:"-",line:a[x-1]});x--;}}
 ops.reverse();if(ops.filter(x=>x.op!=="+").map(x=>x.line).join("\n")!==before||ops.filter(x=>x.op!=="-").map(x=>x.line).join("\n")!==after)throw new Error("diff-reconstruct");
 let ai=0,bi=0;const edits=[];let e=null;
 for(const o of ops){if(o.op==="="){if(e){edits.push(e);e=null;}ai++;bi++;}else{if(!e)e={oldOffset:ai,newOffset:bi,removed:[],added:[]};if(o.op==="-"){e.removed.push(o.line);ai++;}else{e.added.push(o.line);bi++;}}}if(e)edits.push(e);
 const forward=a.slice(),reverse=b.slice();for(const e of edits.slice().reverse()){if(forward.slice(e.oldOffset,e.oldOffset+e.removed.length).join("\n")!==e.removed.join("\n"))throw new Error("fwd-preimage");forward.splice(e.oldOffset,e.removed.length,...e.added);if(reverse.slice(e.newOffset,e.newOffset+e.added.length).join("\n")!==e.added.join("\n"))throw new Error("rev-preimage");reverse.splice(e.newOffset,e.added.length,...e.removed);}
 if(forward.join("\n")!==after||reverse.join("\n")!==before)throw new Error("apply-reverse-mismatch");
 return {beforeLines:N,afterLines:M,added:edits.reduce((s,e)=>s+e.added.length,0),removed:edits.reduce((s,e)=>s+e.removed.length,0),edits,forwardExact:true,reverseExact:true};
}
